import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Cross-Compiling","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Cross-Compiling | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/guide/cross-compiling"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/guide/cross-compiling"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/guide/cross-compiling"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/guide/cross-compiling"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/guide/cross-compiling"}]]},"headers":[],"relativePath":"xclang/guide/cross-compiling.md","filePath":"en/xclang/guide/cross-compiling.md","lastUpdated":1794509097000}'),i={name:"xclang/guide/cross-compiling.md"};function d(n,e,c,l,r,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="cross-compiling" tabindex="-1">Cross-Compiling <a class="header-anchor" href="#cross-compiling" aria-label="Permalink to &quot;Cross-Compiling&quot;">​</a></h1><p>Pass <code>--target=&lt;triple&gt;</code> to <code>clang</code> or <code>clang++</code> to compile and link for another target. Every host archive contains the compiler, <code>lld</code>, and the sysroots, prebuilt runtimes and config files for all bundled targets, so cross-compiling needs no external sysroot or wrapper script.</p><h2 id="build-for-another-target" tabindex="-1">Build for Another Target <a class="header-anchor" href="#build-for-another-target" aria-label="Permalink to &quot;Build for Another Target&quot;">​</a></h2><p>From the <a href="./quick-start">quick start</a> directory (<code>examples/quickstart</code>), compile <code>hello.cpp</code> for Windows on Arm:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-w64-mingw32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-windows-arm64.exe</span></span></code></pre></div><h2 id="targets-and-hosts" tabindex="-1">Targets and Hosts <a class="header-anchor" href="#targets-and-hosts" aria-label="Permalink to &quot;Targets and Hosts&quot;">​</a></h2><p>The same <code>--target</code> flag builds for any of xclang&#39;s ten targets:</p><table tabindex="0"><thead><tr><th>target</th><th>also spelled</th><th>C library</th><th>runs on</th><th>vendor SDK</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td><code>x86_64-pc-linux-gnu</code></td><td>glibc 2.17</td><td>Linux with glibc 2.17 or later</td><td></td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td><code>aarch64-pc-linux-gnu</code>, <code>arm64-unknown-linux-gnu</code>, <code>arm64-pc-linux-gnu</code></td><td>glibc 2.17</td><td>Linux with glibc 2.17 or later</td><td></td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td><code>x86_64-w64-windows-gnu</code>, <code>x86_64-pc-windows-gnu</code></td><td>mingw-w64 14.0.0, UCRT</td><td>Windows 10 or later</td><td></td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td><code>aarch64-w64-windows-gnu</code>, <code>aarch64-pc-windows-gnu</code>, <code>arm64-w64-windows-gnu</code>, <code>arm64-pc-windows-gnu</code></td><td>mingw-w64 14.0.0, UCRT</td><td>Windows 10 or later</td><td></td></tr><tr><td><code>aarch64-apple-darwin</code></td><td><code>aarch64-apple-macos</code>, <code>aarch64-apple-macosx</code>, <code>arm64-apple-darwin</code>, <code>arm64-apple-macos</code>, <code>arm64-apple-macosx</code></td><td>the SDK&#39;s libSystem</td><td>macOS 13.0 or later</td><td>Apple&#39;s, on Linux and Windows hosts</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td><code>x86_64-apple-macos</code>, <code>x86_64-apple-macosx</code></td><td>the SDK&#39;s libSystem</td><td>macOS 13.0 or later</td><td>Apple&#39;s, on Linux and Windows hosts</td></tr><tr><td><code>x86_64-unknown-linux-musl</code></td><td><code>x86_64-pc-linux-musl</code></td><td>musl 1.2.6, static</td><td>any Linux</td><td></td></tr><tr><td><code>aarch64-unknown-linux-musl</code></td><td><code>aarch64-pc-linux-musl</code>, <code>arm64-unknown-linux-musl</code>, <code>arm64-pc-linux-musl</code></td><td>musl 1.2.6, static</td><td>any Linux</td><td></td></tr><tr><td><code>x86_64-pc-windows-msvc</code></td><td><code>x86_64-unknown-windows-msvc</code></td><td>Microsoft&#39;s CRT and UCRT</td><td>Windows 10 or later</td><td>Microsoft&#39;s</td></tr><tr><td><code>aarch64-pc-windows-msvc</code></td><td><code>aarch64-unknown-windows-msvc</code>, <code>arm64-pc-windows-msvc</code>, <code>arm64-unknown-windows-msvc</code></td><td>Microsoft&#39;s CRT and UCRT</td><td>Windows 10 or later</td><td>Microsoft&#39;s</td></tr></tbody></table><p>Every target links xclang&#39;s <code>libc++</code> and <code>compiler-rt</code> statically by default and uses <code>lld</code> as its linker (<code>ld.lld</code>, <code>lld-link</code> or <code>ld64.lld</code>). Programs depend at run time only on the OS libraries of their target family (<a href="./../design/hermeticity">hermeticity</a>).</p><p>All ten targets are <strong>Tier 1</strong>: built for every release and tested on a native GitHub-hosted runner without an emulator (Tier 2 runs tests under emulation or virtualization; Tier 3 compiles and links without running). Other targets are in the <a href="./../design/roadmap#targets">roadmap</a>. Sanitizer support per target is in <a href="./../features/sanitizers">sanitizers</a>.</p><p>A host is a machine the toolchain runs on. Each host has its own archive (<a href="./../reference/releases#assets">releases</a>), and every archive carries all targets above:</p><table tabindex="0"><thead><tr><th>host</th><th>archive built on</th><th>tested on</th><th>what the toolchain needs on the host</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td>Linux x64</td><td><code>ubuntu-24.04</code></td><td>glibc 2.17 or later</td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td>Linux x64, cross-compiled</td><td><code>ubuntu-24.04-arm</code></td><td>glibc 2.17 or later</td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td>Linux x64, cross-compiled (MinGW program)</td><td><code>windows-2025</code></td><td>Windows 10 or later</td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td>Linux x64, cross-compiled (MinGW program)</td><td><code>windows-11-arm</code></td><td>Windows 10 or later</td></tr><tr><td><code>aarch64-apple-darwin</code></td><td>macOS arm64</td><td><code>macos-15</code></td><td>macOS 13 or later; Xcode or the Command Line Tools for macOS targets</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td>macOS arm64, cross-compiled</td><td><code>macos-15-intel</code></td><td>macOS 13 or later; Xcode or the Command Line Tools for macOS targets</td></tr></tbody></table><h2 id="how-clang-finds-a-target-s-files" tabindex="-1">How Clang Finds a Target&#39;s Files <a class="header-anchor" href="#how-clang-finds-a-target-s-files" aria-label="Permalink to &quot;How Clang Finds a Target&#39;s Files&quot;">​</a></h2><p>For each <code>--target</code>, <code>clang</code> reads <code>bin/&lt;triple&gt;.cfg</code> (<code>clang-cl</code> reads <code>bin/&lt;triple&gt;-clang-cl.cfg</code>), with copies for alternate target spellings (<a href="./../design/toolchain">toolchain structure</a>). <code>&lt;CFGDIR&gt;</code> in the config file expands to <code>bin/</code>, pointing <code>clang</code> to the target&#39;s sysroot or SDK, <code>libc++</code> headers, <code>compiler-rt</code>, <code>libunwind</code> and <code>lld</code> (<a href="./../reference/layout">archive layout</a>).</p><p>The config files apply to native builds as well, so <code>clang++ hello.cpp</code> on Linux compiles against the bundled glibc 2.17 sysroot rather than the host&#39;s <code>/usr/include</code> and <code>/usr/lib</code>. Build scripts written for GCC (<code>-latomic</code>, <code>-lgcc</code>, <code>-lgcc_s</code>, <code>-lgcc_eh</code>, <code>-lstdc++</code>) link without changes (<a href="./../design/hermeticity#gcc-library-names">GCC library names</a>). Pass <code>--no-default-config</code> to skip the target config file and run a bare <code>clang</code> that looks for the system&#39;s headers, runtime libraries and linker.</p><h2 id="vendor-sdks" tabindex="-1">Vendor SDKs <a class="header-anchor" href="#vendor-sdks" aria-label="Permalink to &quot;Vendor SDKs&quot;">​</a></h2><p>Two target families build against a vendor SDK that xclang cannot redistribute:</p><ul><li><strong><a href="#macos">macOS targets</a></strong>: on macOS hosts, <code>clang</code> uses the SDK of Xcode or the Command Line Tools. On Linux and Windows hosts, run <code>xclang sdk fetch macos --accept-license</code> once to fetch the macOS SDK from Apple.</li><li><strong><a href="#msvc-targets">Windows MSVC targets</a></strong>: on any host, run <code>xclang sdk fetch windows --accept-license</code> once to fetch Microsoft&#39;s CRT, STL and Windows SDK. On a Windows host with no SDK fetched, <code>clang</code> uses an installed Visual Studio.</li></ul><p><code>xclang sdk fetch</code> unpacks each SDK into <code>&lt;toolchain&gt;/sdk/</code> and points <code>&lt;toolchain&gt;/sdk/macos</code> or <code>&lt;toolchain&gt;/sdk/windows</code> at the active SDK, so the target config files reference a fixed path while SDK versions change (<a href="./../reference/xclang-command">the <code>xclang</code> command</a>). In Bazel, <code>MODULE.bazel</code> accepts the license and a repository rule unpacks the SDK as an external repository (<a href="./../integrations/bazel#build-for-msvc-and-for-macos-anywhere">Bazel</a>).</p><p>Apple&#39;s SDK agreement and Microsoft&#39;s Visual Studio license allow use, not redistribution. <code>xclang sdk fetch</code> prints the vendor&#39;s terms unless you pass <code>--accept-license</code>, and downloads directly from Apple&#39;s and Microsoft&#39;s servers using package URLs, sizes, <code>sha256</code> digests and SDK content digests pinned in <code>xclang/sdk-versions.json</code> to match GitHub&#39;s runner images (<code>macos-latest</code>, <code>windows-2025</code>, <code>windows-2022</code>). Apple&#39;s terms allow use of the macOS SDK on Apple hardware; whether to build for macOS on Linux or Windows with it is the user&#39;s decision under those terms.</p><h2 id="the-platform-s-c-library" tabindex="-1">The Platform&#39;s C++ Library <a class="header-anchor" href="#the-platform-s-c-library" aria-label="Permalink to &quot;The Platform&#39;s C++ Library&quot;">​</a></h2><p>A program that passes C++ types across an interface to a library built with the platform&#39;s C++ library, such as a Linux distribution&#39;s Qt or Boost or a Windows library built with MSVC, must use that same C++ library. Pass <code>-stdlib=platform</code> (or <code>-stdlib=libstdc++</code>; in <code>clang-cl</code>, <code>/clang:-stdlib=platform</code>) to every compile and link command, C files included:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -stdlib=platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -stdlib=platform</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=x86_64-pc-windows-msvc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.exe</span></span></code></pre></div><p>The flag selects <code>bin/&lt;triple&gt;-system.cfg</code> (or <code>&lt;triple&gt;-clang-cl-system.cfg</code>, via <a href="./../reference/patches">patch 0018</a>), which keeps <code>lld</code>, the deployment target and the C runtime, and leaves out xclang&#39;s <code>libc++</code> and bundled sysroot:</p><table tabindex="0"><thead><tr><th>target</th><th>C++ library</th><th>sysroot or SDK</th><th>loaded at run time</th></tr></thead><tbody><tr><td>Linux (glibc)</td><td>GCC&#39;s <code>libstdc++</code>, shared</td><td>the host&#39;s, a distribution&#39;s cross packages (<code>g++-aarch64-linux-gnu</code>), or <code>--sysroot</code></td><td>the system&#39;s <code>libstdc++.so.6</code> and <code>libgcc_s.so.1</code>, and the build&#39;s glibc (not 2.17)</td></tr><tr><td>Linux (musl)</td><td>the sysroot&#39;s <code>libstdc++</code></td><td><code>--sysroot</code>, such as an Alpine root</td><td>what that sysroot links</td></tr><tr><td>Windows (MinGW)</td><td>the sysroot&#39;s <code>libstdc++</code></td><td><code>--sysroot</code>, such as MSYS2&#39;s <code>ucrt64</code> or a directory linking a distribution&#39;s <code>mingw-w64</code></td><td>what that sysroot links</td></tr><tr><td>Windows (MSVC)</td><td>Microsoft&#39;s STL</td><td>the fetched Windows SDK, or Visual Studio on Windows</td><td>nothing more: the STL is linked statically, with the hybrid CRT</td></tr><tr><td>macOS</td><td>the SDK&#39;s <code>libc++</code></td><td>Xcode&#39;s SDK, or the SDK fetched with <code>xclang sdk fetch macos</code></td><td><code>/usr/lib/libc++.1.dylib</code> of the OS</td></tr></tbody></table><p>For MinGW on Debian or Ubuntu, point <code>--sysroot</code> to a directory containing two symbolic links, <code>x86_64-w64-mingw32</code> to <code>/usr/x86_64-w64-mingw32</code> and <code>lib/gcc</code> to <code>/usr/lib/gcc</code> (passing <code>--sysroot=/usr</code> directly would add the Linux host&#39;s <code>/usr/include</code> and <code>/usr/lib</code>).</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><h3 id="glibc-2-17-floor-static-pie-and-pg" tabindex="-1">glibc 2.17 Floor, <code>-static-pie</code> and <code>-pg</code> <a class="header-anchor" href="#glibc-2-17-floor-static-pie-and-pg" aria-label="Permalink to &quot;glibc 2.17 Floor, `-static-pie` and `-pg`&quot;">​</a></h3><p><code>x86_64-unknown-linux-gnu</code> and <code>aarch64-unknown-linux-gnu</code> compile and link against the bundled glibc 2.17 sysroot in <code>&lt;toolchain&gt;/&lt;triple&gt;/</code>, the oldest glibc version the resulting binary can run on (<a href="./../design/hermeticity#why-glibc-2-17">why glibc 2.17</a>; a newer glibc target is <a href="./../design/roadmap#glibc-newer">considered</a>).</p><ul><li><strong>No <code>-static-pie</code></strong>: glibc 2.17 has no <code>rcrt1.o</code>. Use <code>-static</code> for a static glibc binary, or build for a <a href="#musl-targets">musl target</a>, which supports <code>-static-pie</code>.</li><li><strong><code>-pg</code> requires <code>-no-pie</code></strong>: glibc 2.17&#39;s <code>gcrt1.o</code> is not compiled as position-independent code.</li><li><strong>No <code>quadmath.h</code></strong>: <code>libquadmath</code> is a GCC library; <code>__float128</code> arithmetic itself works through <code>clang</code> and <code>compiler-rt</code>.</li><li><strong><code>-nodefaultlibs</code> and <code>libunwind</code></strong>: because <code>libgcc_s.a</code> in the sysroot is an empty archive, linking with <code>-nodefaultlibs</code> (as <code>rustc</code> does for <code>*-unknown-linux-gnu</code>) provides no unwinder. Build Rust projects with <code>xclang cargo</code> or pass <code>-Clink-arg=-l:libunwind.a</code> (<a href="./../integrations/cargo">Rust and Cargo</a>).</li></ul><h3 id="musl-targets" tabindex="-1">musl Targets <a class="header-anchor" href="#musl-targets" aria-label="Permalink to &quot;musl Targets&quot;">​</a></h3><p><code>x86_64-unknown-linux-musl</code> and <code>aarch64-unknown-linux-musl</code> link musl 1.2.6 (with upstream security patches, unwind tables for C callbacks, and Linux 6.18 UAPI headers) and every runtime statically into the executable:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=x86_64-unknown-linux-musl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-static-x64</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-unknown-linux-musl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-static-arm64</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llvm-readelf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --program-headers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-static-x64</span></span></code></pre></div><p>The binary has no <code>INTERP</code> program header and no dynamic section, makes system calls directly to the Linux kernel, and runs on any Linux of its architecture.</p><ul><li><strong><code>-static</code> by default, <code>-static-pie</code> on request</strong>: the config file passes <code>-static</code>, producing an <code>ET_EXEC</code> binary so <code>-no-pie</code> from CMake or <code>rustc</code> is not rejected. Pass <code>-static-pie</code> on the command line to build a position-independent static binary with <code>rcrt1.o</code> for ASLR.</li><li><strong>No shared libraries</strong>: the sysroot is built with <code>--disable-shared</code> and has no <code>libc.so</code>. Dynamic linking against musl, <code>dlopen</code>, and building <code>-shared</code> libraries are not supported with the bundled sysroot (use <a href="#the-platform-s-c-library"><code>-stdlib=platform</code></a> with <code>--sysroot</code> for dynamic musl builds).</li></ul><p>Where musl&#39;s runtime behavior differs from glibc&#39;s (measured on 4-core GitHub Linux x64 runners):</p><ul><li><strong><code>malloc</code> under threads</strong>: musl&#39;s allocator uses a lock that threads contend for. Four million <code>malloc</code> and <code>free</code> calls of 16 to 528 bytes took 0.21 s on one thread (glibc: 0.07 s) and 4.8 s across four threads at once (glibc: 0.12 s). Link an allocator of your own into programs that allocate heavily across threads.</li><li><strong>Locales</strong>: musl has no locale data and formats as the <code>C</code> locale: <code>printf(&quot;%&#39;.1f&quot;, 1234567.5)</code> prints <code>1234567.5</code> under <code>en_US.UTF-8</code> where glibc prints <code>1,234,567.5</code>, and <code>libc++</code>&#39;s <code>std::locale</code> behaves the same way.</li><li><strong>Name lookup</strong>: musl reads <code>/etc/hosts</code> and <code>/etc/resolv.conf</code> and queries DNS directly without NSS (<code>nsswitch.conf</code> modules), so mDNS <code>.local</code> names and LDAP or SSSD users and groups are not resolved through it.</li></ul><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>Both the MinGW and MSVC targets use UCRT, part of Windows 10 and later (<a href="./../design/windows">Windows design</a>).</p><h3 id="mingw-targets" tabindex="-1">MinGW Targets <a class="header-anchor" href="#mingw-targets" aria-label="Permalink to &quot;MinGW Targets&quot;">​</a></h3><p><code>x86_64-w64-mingw32</code> and <code>aarch64-w64-mingw32</code> ship in every toolchain archive and link <code>libc++</code>, <code>libc++abi</code>, <code>libunwind</code>, <code>winpthreads</code> and <code>compiler-rt</code> statically with <code>ld.lld</code>.</p><ul><li><strong><code>.exe</code> output names</strong>: a MinGW link appends <code>.exe</code> to an output name without an extension on every host (<code>-o hello</code> writes <code>hello.exe</code>).</li><li><strong>Headers and <code>--gc-sections</code></strong>: MinGW-w64&#39;s headers are lowercase (<code>windows.h</code>, <code>basetsd.h</code>, <code>winsock2.h</code>); use lowercase <code>#include</code> names so builds succeed on case-sensitive file systems, and avoid passing <code>-Wl,--gc-sections</code> when unreferenced COMDAT initializers register tests (<a href="./../design/windows#gc-sections-and-static-initializers"><code>gc-sections</code> and static initializers</a>).</li><li><strong>Rust&#39;s <code>-gnullvm</code> targets</strong>: use <code>x86_64-pc-windows-gnullvm</code> and <code>aarch64-pc-windows-gnullvm</code> rather than <code>*-pc-windows-gnu</code>. The <code>-gnullvm</code> targets link <code>libunwind</code> and UCRT, matching xclang&#39;s MinGW sysroots (<a href="./../integrations/cargo">Rust and Cargo</a>).</li></ul><h3 id="msvc-targets" tabindex="-1">MSVC Targets <a class="header-anchor" href="#msvc-targets" aria-label="Permalink to &quot;MSVC Targets&quot;">​</a></h3><p><code>x86_64-pc-windows-msvc</code> and <code>aarch64-pc-windows-msvc</code> build for the MSVC ABI, needed when linking libraries compiled with MSVC, COM-heavy code or Windows vendor SDKs. Fetch Microsoft&#39;s CRT, STL and Windows SDK once, then build from any host with <code>clang++</code> or <code>clang-cl</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xclang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> windows</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --accept-license</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=x86_64-pc-windows-msvc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-msvc-x64.exe</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang-cl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /O2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /EHsc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Fehello-cl.exe</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang-cl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /O2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /EHsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-pc-windows-msvc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Fehello-cl-arm64.exe</span></span></code></pre></div><ul><li><p><strong>Choosing SDK versions</strong>: by default, <code>xclang sdk fetch windows</code> fetches the <code>windows-latest</code> preset (<code>windows-2025-vs2026</code>: MSVC 14.51 and Windows SDK 10.0.26100). Pass <code>--preset windows-2022</code> for MSVC 14.44, or pass <code>--msvc-version</code>, <code>--sdk-version</code> and <code>--arch x86_64,aarch64,x86</code>. <code>xclang sdk use &lt;name&gt;</code> switches the active SDK (<a href="./../reference/xclang-command">the <code>xclang</code> command</a>). On a Windows host without a fetched SDK (or with <code>--no-default-config</code>), <code>clang</code> uses an installed Visual Studio; on Linux and macOS hosts without a fetched SDK, compiling a file that includes a CRT header stops immediately (<code>-ffreestanding</code> works without an SDK).</p></li><li><p><strong><code>clang-cl</code></strong>: a plain <code>clang-cl</code> command reads <code>&lt;host-triple&gt;-clang-cl.cfg</code> and builds for the host architecture&#39;s MSVC target without <code>--target</code>. On macOS, <code>clang-cl</code> treats an input path such as <code>/Users/me/hello.cpp</code> as its <code>/U</code> option: put inputs after <code>--</code>, or name them with <code>/Tp</code>. In <a href="./../integrations/cmake">CMake</a> and <a href="./../integrations/bazel">Bazel</a>, xclang uses the GNU-style <code>clang++</code> driver rather than <code>clang-cl</code>.</p></li><li><p><strong>C runtime choices</strong>: by default, binaries link <code>libc++</code> (or Microsoft&#39;s STL) and the VC runtime (<code>libvcruntime.lib</code>, <code>libcmt.lib</code>) statically and UCRT dynamically against <code>ucrtbase.dll</code> (the hybrid CRT; <a href="./../design/windows#the-hybrid-crt">Windows design</a>). To select another C runtime:</p><table tabindex="0"><thead><tr><th>C runtime</th><th><code>clang</code>, <code>clang++</code></th><th><code>clang-cl</code></th></tr></thead><tbody><tr><td>hybrid CRT (default)</td><td>(default)</td><td><code>/MT</code> (default)</td></tr><tr><td>DLL runtime (<code>vcruntime140.dll</code>, plus <code>msvcp140.dll</code> with the STL)</td><td><code>-fms-runtime-lib=dll</code></td><td><code>/MD</code></td></tr><tr><td>all static, UCRT included</td><td><code>-Wl,/nodefaultlib:ucrt.lib -llibucrt</code></td><td><code>/link /nodefaultlib:ucrt.lib libucrt.lib</code></td></tr><tr><td>static debug CRT</td><td><code>-fms-runtime-lib=static_dbg -Wl,/nodefaultlib:ucrt.lib</code></td><td><code>/MTd /link /nodefaultlib:ucrt.lib</code></td></tr></tbody></table><p><code>/MDd</code> loads <code>ucrtbased.dll</code>, which only Visual Studio installs.</p></li><li><p><strong>The C++ standard</strong>: <code>clang</code> defaults to C++14 for MSVC targets, matching <code>cl.exe</code>. Microsoft&#39;s STL exposes some C++17 library templates such as <code>std::is_integral_v</code> in C++14 mode, whereas <code>libc++</code> provides them only from C++17 onward; pass <code>-std=c++17</code> (<code>/std:c++17</code>) or later when code relies on them.</p></li></ul><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>The macOS targets, <code>aarch64-apple-darwin</code> and <code>x86_64-apple-darwin</code>, compile against Apple&#39;s macOS SDK and link xclang&#39;s <code>libc++</code> and <code>libc++abi</code> statically with <code>ld64.lld</code> (<a href="./../design/macos">macOS design</a>).</p><h3 id="on-macos-hosts" tabindex="-1">On macOS Hosts <a class="header-anchor" href="#on-macos-hosts" aria-label="Permalink to &quot;On macOS Hosts&quot;">​</a></h3><p>On a macOS host, <code>clang</code> uses the SDK of Xcode or the Command Line Tools without fetching anything through <code>xclang</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-apple-darwin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-macos-arm64</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=x86_64-apple-darwin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-macos-x64</span></span></code></pre></div><h3 id="on-linux-and-windows-hosts" tabindex="-1">On Linux and Windows Hosts <a class="header-anchor" href="#on-linux-and-windows-hosts" aria-label="Permalink to &quot;On Linux and Windows Hosts&quot;">​</a></h3><p>On Linux and Windows hosts, fetch Apple&#39;s macOS SDK once with <code>xclang sdk fetch macos --accept-license</code>, then build for either macOS architecture with <code>--target</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xclang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macos</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --accept-license</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=arm64-apple-macos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-macos-arm64</span></span></code></pre></div><table tabindex="0"><thead><tr><th>host</th><th>SDK used</th></tr></thead><tbody><tr><td>macOS</td><td>the last <code>-isysroot</code>, else <code>SDKROOT</code>, else Xcode&#39;s (<code>xcselect</code>)</td></tr><tr><td>Linux, Windows</td><td>the last <code>-isysroot</code> on the command line, else <code>&lt;toolchain&gt;/sdk/macos</code></td></tr></tbody></table><p>On Linux and Windows hosts, the target config file begins with <code>-isysroot &lt;CFGDIR&gt;/../sdk/macos</code>. Because <code>clang</code> reads <code>SDKROOT</code> only when no <code>-isysroot</code> flag is present, and <code>--sysroot</code> affects only the link step, pass <code>-isysroot &lt;dir&gt;</code> on the command line to select another SDK (Cargo, <code>rustc</code> and xclang&#39;s <a href="./../integrations/cmake">CMake</a> package pass <code>SDKROOT</code> as <code>-isysroot</code>).</p><h3 id="presets-and-versions" tabindex="-1">Presets and Versions <a class="header-anchor" href="#presets-and-versions" aria-label="Permalink to &quot;Presets and Versions&quot;">​</a></h3><ul><li><strong>Presets</strong>: by default, <code>xclang sdk fetch macos</code> uses the <code>macos-latest</code> preset (<code>macOS-26-arm64</code>, SDK 26.5). Pass <code>--preset macos-15</code> (or <code>macOS-26</code>, <code>macOS-15-arm64</code>) to match that GitHub Actions runner image.</li><li><strong>Pinned versions</strong>: pass <code>--version &lt;ver&gt;</code> (such as <code>--version 15</code> or <code>--version 15.5</code>) to pick the newest matching SDK pinned in <code>xclang/sdk-versions.json</code>, and run <code>xclang sdk use &lt;name&gt;</code> to switch <code>&lt;toolchain&gt;/sdk/macos</code> between fetched versions (<a href="./../reference/xclang-command">the <code>xclang</code> command</a>).</li><li><strong><code>--version latest</code></strong>: queries Apple&#39;s live software update catalogs for the newest SDK available when the command runs; it is unpinned and not reproducible.</li><li><strong>Withdrawn packages</strong>: when Apple withdraws a Command Line Tools package from its CDN and posts a re-signed package in its place, <code>xclang sdk fetch</code> falls back to Apple&#39;s catalogs and verifies the unpacked SDK by its content digest (<a href="./../design/macos#packages-apple-withdraws-and-content-digests">macOS design</a>).</li></ul><h3 id="stdlib-platform-and-the-deployment-target" tabindex="-1"><code>-stdlib=platform</code> and the Deployment Target <a class="header-anchor" href="#stdlib-platform-and-the-deployment-target" aria-label="Permalink to &quot;`-stdlib=platform` and the Deployment Target&quot;">​</a></h3><p>The target config file sets <code>-mmacos-version-min=13.0</code>; pass a later <code>-mmacos-version-min=&lt;ver&gt;</code> on the command line to override it. With xclang&#39;s default static <code>libc++</code>, standard library features depend on the xclang release rather than the target macOS version. With <code>-stdlib=platform</code> (which links <code>/usr/lib/libc++.1.dylib</code> of the OS), newer C++ library symbols require a matching deployment target: for example, <code>std::format</code> of a floating-point number requires <code>-mmacos-version-min=13.3</code> or later.</p><h3 id="ld64-lld-and-fuse-ld-ld" tabindex="-1"><code>ld64.lld</code> and <code>-fuse-ld=ld</code> <a class="header-anchor" href="#ld64-lld-and-fuse-ld-ld" aria-label="Permalink to &quot;`ld64.lld` and `-fuse-ld=ld`&quot;">​</a></h3><p>macOS targets link with <code>ld64.lld</code> on every host. <code>ld64.lld</code> signs <code>arm64</code> binaries ad hoc so they run on Apple silicon without invoking <code>codesign</code>, and <code>llvm-install-name-tool</code> re-signs binaries when modifying them. Signing with a Developer ID certificate and notarizing require Apple&#39;s tools, and compiling <code>.nib</code>, <code>.xib</code> or asset catalogs requires <code>actool</code> and <code>ibtool</code> on macOS.</p><p>On a macOS host, pass <code>-fuse-ld=ld</code> to link non-LTO object files with Apple&#39;s <code>ld</code> instead. Because xclang does not ship <code>libLTO.dylib</code>, LTO builds always link with <code>ld64.lld</code>.</p><h3 id="two-architectures" tabindex="-1">Two Architectures <a class="header-anchor" href="#two-architectures" aria-label="Permalink to &quot;Two Architectures&quot;">​</a></h3><p>Every host archive carries both <code>aarch64-apple-darwin</code> and <code>x86_64-apple-darwin</code>, and <code>llvm-lipo</code> combines binaries of both into a universal binary. In CMake on a macOS host, building for the other macOS architecture sets <code>CMAKE_OSX_ARCHITECTURES</code> rather than cross-compiling (<a href="./../integrations/cmake">CMake</a>).</p><h2 id="running-what-you-built" tabindex="-1">Running What You Built <a class="header-anchor" href="#running-what-you-built" aria-label="Permalink to &quot;Running What You Built&quot;">​</a></h2><p>Inspect the format and architecture of the cross-compiled binary with <code>llvm-readobj</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llvm-readobj</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file-headers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-windows-arm64.exe</span></span></code></pre></div><p>Among the headers, it prints <code>Format: COFF-ARM64</code> and <code>Arch: aarch64</code>. Copy the binary to a machine of its target and run it; no runtime package needs to be installed. Some hosts also run binaries of another architecture of the same OS:</p><ul><li><code>arm64</code> macOS runs <code>x86_64</code> macOS binaries through Rosetta.</li><li>Windows on Arm runs <code>x86_64</code> Windows binaries through emulation.</li></ul><p>Building on one runner and running tests on a runner of the target is covered in <a href="./../integrations/ci#build-on-one-runner-run-on-another">CI</a>.</p><h2 id="in-your-build-system" tabindex="-1">In Your Build System <a class="header-anchor" href="#in-your-build-system" aria-label="Permalink to &quot;In Your Build System&quot;">​</a></h2><ul><li><a href="./../integrations/cmake">CMake</a>: pass the toolchain file with <code>-DXCLANG_TARGET=&lt;target&gt;</code>.</li><li><a href="./../integrations/bazel">Bazel</a>: pass <code>--platforms=@xclang//platforms:&lt;target&gt;</code>.</li><li><a href="./../integrations/clang">Plain clang, Make and Meson</a>: pass <code>--target=&lt;target&gt;</code> to the compiler, or in a Meson cross file.</li><li><a href="./../integrations/cargo">Rust and Cargo</a>: run <code>xclang cargo build --target &lt;rust-target&gt;</code>.</li></ul><h2 id="build-tools-minimum-versions" tabindex="-1">Build Tools&#39; Minimum Versions <a class="header-anchor" href="#build-tools-minimum-versions" aria-label="Permalink to &quot;Build Tools&#39; Minimum Versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>tool</th><th>minimum version or target</th><th>why</th></tr></thead><tbody><tr><td>CMake</td><td>3.28 or later</td><td>the first version that builds C++20 modules without experimental switches; <code>find_package(xclang)</code> rejects older versions (<a href="./../integrations/cmake">CMake</a>)</td></tr><tr><td>Ninja</td><td>1.11 or later</td><td>required by CMake for C++20 modules; only the Ninja generators build modules for these targets</td></tr><tr><td>Bazel</td><td>9, with <code>rules_cc</code> 0.2.25 or later</td><td>the toolchains build on <code>rules_cc</code> 0.2.28&#39;s unix config (<a href="./../design/bazel-module">the Bazel module</a>); C++20 modules require <code>--experimental_cpp_modules</code></td></tr><tr><td>Rust</td><td><code>*-pc-windows-gnullvm</code> for MinGW (not <code>*-windows-gnu</code>); <code>*-pc-windows-msvc</code> with the Windows SDK</td><td><code>*-windows-gnullvm</code>&#39;s standard library links <code>libunwind</code> and UCRT, matching xclang&#39;s MinGW sysroots (<a href="./../integrations/cargo">Rust and Cargo</a>)</td></tr></tbody></table>',75)])])}const u=t(i,[["render",d]]);export{g as __pageData,u as default};
